/* practice with Dukkha */
#include <stdio.h>

#define N	100
#define X	100
#define MD	1000000007

long long power(int a, int k) {
	long long p;

	if (k == 0)
		return 1;
	p = power(a, k >> 1);
	p = p * p % MD;
	if (k & 1)
		p = p * a % MD;
	return p;
}

int main() {
	static int ff[X + 1], ds[X + 1][N][N + 1], dp[X + 1][N], dq[X + 1][N], dr[X + 1];
	static char cc[N + 1];
	int n, x, i, l, r, m;

	scanf("%d%d%s", &n, &x, cc);
	if (x == 0) {
		printf("%d\n", n == 1 && cc[0] == '0');
		return 0;
	}
	ff[0] = ff[1] = 1;
	for (i = 2; i <= x; i++)
		ff[i] = (ff[i - 1] + ff[i - 2]) % (MD - 1);
	for (i = 0; i <= x; i++)
		ff[i] = power(2, ff[i]);
	for (l = 0; l < n; l++) {
		ds[0][l][l] = ds[1][l][l] = 1;
		ds[0][l][l + 1] = cc[l] == '0' ? 1 : 0;
		ds[1][l][l + 1] = cc[l] == '1' ? 1 : 0;
	}
	for (i = 2; i <= x; i++)
		for (l = 0; l < n; l++)
			for (r = l; r < n; r++) {
				long long z = 0;

				for (m = l; m <= r; m++)
					z = (z + (long long) ds[i - 1][l][m] * ds[i - 2][m][r]) % MD;
				ds[i][l][r] = z;
			}
	if (n > 1) {
		dp[0][n - 1] = ds[0][n - 1][n];
		dp[1][n - 1] = ds[1][n - 1][n];
		for (i = 2; i <= x; i++)
			for (l = 1; l < n; l++) {
				long long z = (long long) dp[i - 1][l] * ff[i - 2] % MD;

				for (m = l; m < n; m++)
					z = (z + (long long) ds[i - 1][l][m] * dp[i - 2][m]) % MD;
				dp[i][l] = z;
			}
		dq[0][1] = ds[0][0][1];
		dq[1][1] = ds[1][0][1];
		for (i = 2; i <= x; i++)
			for (r = 1; r < n; r++) {
				long long z = (long long) ff[i - 1] * dq[i - 2][r] % MD;

				for (m = r; m > 0; m--)
					z = (z + (long long) dq[i - 1][m] * ds[i - 2][m][r]) % MD;
				dq[i][r] = z;
			}
	}
	dr[0] = ds[0][0][n];
	dr[1] = ds[1][0][n];
	for (i = 2; i <= x; i++) {
		long long z = ((long long) dr[i - 1] * ff[i - 2] + (long long) ff[i - 1] * dr[i - 2]) % MD;

		for (m = 1; m < n; m++)
			z = (z + (long long) dq[i - 1][m] * dp[i - 2][m]) % MD;
		dr[i] = z;
	}
	printf("%d\n", dr[x]);
	return 0;
}
